"""Top 100 TV Series and Legendary High-Rated Episodes Database.

Curated catalog of greatest television series and highest-rated episodes
of all time with ratings from IMDb, Rotten Tomatoes, and Metacritic.
"""

from typing import Dict, List, Any

def calculate_series_cinescore(imdb: float, rt: int, meta: int) -> float:
    """Calculates weighted CineScore (0-100) for TV series."""
    norm_imdb = (imdb / 10.0) * 100
    norm_rt = float(rt)
    norm_meta = float(meta)
    return round((norm_imdb * 0.45) + (norm_rt * 0.35) + (norm_meta * 0.20), 1)

