# Generate Master Series DB with CineScore
MASTER_SERIES_DB: List[Dict[str, Any]] = []
for idx, s in enumerate(RAW_TOP_100_SERIES, 1):
    s_copy = dict(s)
    s_copy["id"] = f"series_top100_{idx:03d}"
    s_copy["rank_top100"] = idx
    s_copy["media_type"] = "tv_series"
    s_copy["cinescore"] = calculate_series_cinescore(s_copy["imdb_rating"], s_copy["rotten_tomatoes_pct"], s_copy["metacritic_score"])
    MASTER_SERIES_DB.append(s_copy)
